mapper.select:
select t_system_org.org_abbreviation
from t_system_org
where t_system_org.org_no = #{orgNo}

select t_system_org.org_name
from t_system_org
where t_system_org.parent_id = #{parentId}

select t_system_org.org_name
from t_system_org
where t_system_org.parent_id = #{parentId}
  and t_system_org.id != #{id}

select count(t_system_org.id)
from t_system_org
where t_system_org.parent_id = #{parentId}

mapper.update:
UPDATE t_system_org
SET t_system_org.status = #{status}
WHERE t_system_org.parent_id = #{parentId}

mapper.select:
select org_no_abbreviation AS orgNoAbbreviation
from t_system_org
where org_no = #{orgNo}

select org_no AS orgNo
from t_system_org
where org_no_abbreviation like CONCAT(#{orgNoAbbreviation}, '%');
